// =============================================================================
// RECOVERY LUCAS ? Reprocesa oportunidades GHL desde 2026-07-28
// =============================================================================
// Objetivo:
// - Recuperar oportunidades que fallaron en n8n por errores del flujo anterior.
// - Consultar GHL directamente y reenviar payload normalizado al Apps Script actual.
// - No usa URL ni URLSearchParams porque en n8n 2.4.8 pueden no estar disponibles
//   dentro del sandbox del Code node.
// =============================================================================

const cfgEnvelope = $('Config Cliente').first().json || {};
const cfg = cfgEnvelope.config || {};

const RECOVERY_START_LOCAL = '2026-07-28T00:00:00-03:00';
const RECOVERY_END_LOCAL = ''; // vac?o = ahora
const PIPELINE_KEYS_TO_SCAN = ['booking', 'sales'];
const PAGE_LIMIT = 100;
const MAX_PAGES_PER_PIPELINE = 60;
const DRY_RUN = false;
const SEND_DELAY_MS = 350;
const REQUEST_DELAY_MS = 120;
const APP_SCRIPT_RETRIES = 4;

if (!cfg.ghl_token) throw new Error('Falta cfg.ghl_token en Config Cliente');
if (!cfg.location_id) throw new Error('Falta cfg.location_id en Config Cliente');
if (!cfg.apps_script_url) throw new Error('Falta cfg.apps_script_url en Config Cliente');

const httpRequest = this.helpers.httpRequest.bind(this.helpers);

function sleep(ms) {
  return new Promise(resolve => setTimeout(resolve, ms));
}

function encodeQuery(query) {
  const parts = [];
  for (const [key, value] of Object.entries(query || {})) {
    if (value === undefined || value === null || value === '') continue;
    if (Array.isArray(value)) {
      for (const item of value) {
        if (item === undefined || item === null || item === '') continue;
        parts.push(encodeURIComponent(key) + '=' + encodeURIComponent(String(item)));
      }
    } else {
      parts.push(encodeURIComponent(key) + '=' + encodeURIComponent(String(value)));
    }
  }
  return parts.join('&');
}

function buildGhlUrl(path, query) {
  const base = 'https://services.leadconnectorhq.com';
  const cleanPath = String(path || '').startsWith('/') ? String(path) : '/' + String(path || '');
  const qs = encodeQuery(query || {});
  return base + cleanPath + (qs ? '?' + qs : '');
}

async function ghlGet(path, query) {
  const url = buildGhlUrl(path, query || {});
  await sleep(REQUEST_DELAY_MS);
  const response = await httpRequest({
    method: 'GET',
    url,
    headers: {
      Authorization: 'Bearer ' + cfg.ghl_token,
      Version: '2021-07-28',
      Accept: 'application/json'
    },
    json: true,
    timeout: 30000
  });
  return typeof response === 'string' ? JSON.parse(response) : response;
}

async function appsScriptPost(payload) {
  if (DRY_RUN) {
    return { ok: true, dry_run: true, message: 'DRY_RUN: no enviado a Apps Script' };
  }

  let lastError = null;
  for (let attempt = 1; attempt <= APP_SCRIPT_RETRIES; attempt++) {
    try {
      const response = await httpRequest({
        method: 'POST',
        url: cfg.apps_script_url,
        headers: { 'Content-Type': 'application/json' },
        body: payload,
        json: true,
        timeout: 60000
      });

      const out = typeof response === 'string' ? JSON.parse(response) : response;
      const msg = String((out && out.message) || '').toLowerCase();
      const lockBusy = msg.includes('lock timeout') || msg.includes('webhook ocupado') || msg.includes('bloqueio') || msg.includes('bloqueo');
      if (out && out.ok === false && lockBusy && attempt < APP_SCRIPT_RETRIES) {
        await sleep(2500 * attempt);
        continue;
      }
      return out;
    } catch (err) {
      lastError = err;
      if (attempt < APP_SCRIPT_RETRIES) {
        await sleep(2500 * attempt);
        continue;
      }
    }
  }
  throw lastError || new Error('Apps Script POST fall? sin detalle');
}

function firstValue(...values) {
  for (const value of values) {
    if (value === undefined || value === null) continue;
    const str = String(value).trim();
    if (str !== '') return value;
  }
  return '';
}

function normalizeText(text) {
  return String(text || '')
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .trim();
}

function arrayify(value) {
  if (Array.isArray(value)) return value;
  if (value === undefined || value === null || value === '') return [];
  if (typeof value === 'object') return Object.values(value).filter(v => v !== undefined && v !== null && String(v).trim() !== '');
  return [value];
}

function deepGet(obj, path) {
  const parts = String(path || '').split('.');
  let current = obj;
  for (const part of parts) {
    if (current === undefined || current === null) return '';
    current = current[part];
  }
  return current === undefined || current === null ? '' : current;
}

function userNameFrom(value) {
  const raw = String(value || '').trim();
  if (!raw) return '';
  if (cfg.user_map && cfg.user_map[raw]) return cfg.user_map[raw];
  const lower = raw.toLowerCase();
  if (cfg.user_email_map && cfg.user_email_map[lower]) return cfg.user_email_map[lower];
  return raw;
}

function resolveOwnerName(...values) {
  for (const value of values) {
    const mapped = userNameFrom(value);
    if (mapped) return mapped;
  }
  return '';
}

function normalizeStageAlias(stageName) {
  const clean = String(stageName || '').trim();
  return (cfg.stage_aliases && cfg.stage_aliases[clean]) || clean;
}

function pipelineNameById(pipelineId) {
  for (const pipe of Object.values(cfg.pipelines || {})) {
    if (pipe && pipe.id === pipelineId) return pipe.name || '';
  }
  return '';
}

function pipelineByKey(key) {
  const pipe = cfg.pipelines && cfg.pipelines[key];
  if (!pipe || !pipe.id) return null;
  return { key, id: pipe.id, name: pipe.name || pipelineNameById(pipe.id) || key };
}

function getOpportunityObject(response) {
  if (!response) return {};
  if (response.opportunity) return response.opportunity;
  if (response.data && response.data.opportunity) return response.data.opportunity;
  if (response.data && !Array.isArray(response.data)) return response.data;
  return response;
}

function getContactObject(response) {
  if (!response) return {};
  if (response.contact) return response.contact;
  if (response.data && response.data.contact) return response.data.contact;
  if (response.data && !Array.isArray(response.data)) return response.data;
  return response;
}

function collectCustom(entity) {
  const out = {};
  if (!entity || typeof entity !== 'object') return out;

  function addKeyVal(key, value) {
    if (!key) return;
    if (value === undefined || value === null) return;
    out[String(key)] = value;
  }

  const candidates = [entity.custom, entity.customData, entity.customFields, entity.customField];
  for (const custom of candidates) {
    if (!custom) continue;
    if (Array.isArray(custom)) {
      for (const field of custom) {
        if (!field || typeof field !== 'object') continue;
        const key = firstValue(field.fieldKey, field.key, field.id, field.name, field.fieldId);
        const value = firstValue(field.value, field.fieldValue, field.values, field.val);
        addKeyVal(key, value);
      }
    } else if (typeof custom === 'object') {
      for (const [key, value] of Object.entries(custom)) addKeyVal(key, value);
    }
  }
  return out;
}

function mergeCustom(...entities) {
  return Object.assign({}, ...entities.map(collectCustom));
}

function customValue(custom, key) {
  if (!custom) return '';
  if (custom[key] !== undefined && custom[key] !== null && String(custom[key]).trim() !== '') return custom[key];
  const normKey = normalizeText(key);
  for (const [k, v] of Object.entries(custom)) {
    if (normalizeText(k) === normKey && v !== undefined && v !== null && String(v).trim() !== '') return v;
  }
  return '';
}

function getNotesText(notesResponse) {
  const root = notesResponse || {};
  const notes = root.notes || root.data || root.items || (Array.isArray(root) ? root : []);
  if (!Array.isArray(notes)) return '';
  return notes.map(note => firstValue(note.body, note.note, note.text, note.message, note.content)).filter(Boolean).join('\n');
}

function getAppointmentsArray(response) {
  const root = response || {};
  if (Array.isArray(root)) return root;
  if (Array.isArray(root.events)) return root.events;
  if (Array.isArray(root.appointments)) return root.appointments;
  if (Array.isArray(root.data)) return root.data;
  if (root.data && Array.isArray(root.data.events)) return root.data.events;
  if (root.data && Array.isArray(root.data.appointments)) return root.data.appointments;
  return [];
}

function getAppointmentId(appt) {
  return firstValue(appt && appt.id, appt && appt.appointmentId, appt && appt.eventId, appt && appt.calendarEventId);
}

function getAppointmentStart(appt) {
  return firstValue(appt && appt.startTime, appt && appt.start_time, appt && appt.start, appt && appt.date, appt && appt.selectedSlot);
}

function getAppointmentCalendarId(appt) {
  return firstValue(appt && appt.calendarId, appt && appt.calendar_id, appt && appt.calendar && appt.calendar.id);
}

function getAppointmentTitle(appt) {
  return firstValue(appt && appt.title, appt && appt.name, appt && appt.calendarName, appt && appt.calendar_name, appt && appt.calendar && appt.calendar.name);
}

function detectAppointmentType(appt) {
  const calendarId = getAppointmentCalendarId(appt);
  const haystack = normalizeText([calendarId, getAppointmentTitle(appt)].filter(Boolean).join(' '));

  for (const [key, route] of Object.entries(cfg.calendars || {})) {
    if (!route || route.enabled === false) continue;
    if (route.calendar_id && calendarId && String(route.calendar_id) === String(calendarId)) {
      return { type: route.type || key.toUpperCase(), reason: 'calendar_id', matchedValue: calendarId };
    }
    const terms = arrayify(route.match_terms);
    const matched = terms.some(term => haystack.includes(normalizeText(term)));
    if (matched) return { type: route.type || key.toUpperCase(), reason: 'match_terms', matchedValue: getAppointmentTitle(appt) };
  }

  return { type: '', reason: '', matchedValue: '' };
}

function normalizeAppointment(appt, detection) {
  if (!appt || !detection || !detection.type) return null;
  return {
    appointment_id: getAppointmentId(appt),
    calendar_id: getAppointmentCalendarId(appt),
    calendar_name: firstValue(appt.calendarName, appt.calendar_name, appt.calendar && appt.calendar.name, ''),
    calendar_title: getAppointmentTitle(appt),
    start_time: getAppointmentStart(appt),
    end_time: firstValue(appt.endTime, appt.end_time, appt.end),
    appointment_status: firstValue(appt.appointmentStatus, appt.appoinmentStatus, appt.status),
    assigned_user_id: firstValue(appt.assignedUserId, appt.assigned_user_id),
    detected_type: detection.type,
    detected_by: detection.reason,
    detected_value: detection.matchedValue,
    source: 'recovery_ghl_api'
  };
}

function parseDateMs(value) {
  if (value === undefined || value === null || value === '') return NaN;
  if (value instanceof Date) return value.getTime();
  let text = String(value).trim();
  if (!text) return NaN;
  if (/^\d{4}-\d{2}-\d{2} \d{2}:\d{2}/.test(text)) text = text.replace(' ', 'T') + '-03:00';
  if (/^\d{4}-\d{2}-\d{2}$/.test(text)) text += 'T00:00:00-03:00';
  const ms = Date.parse(text);
  return Number.isFinite(ms) ? ms : NaN;
}

function opportunityUpdatedMs(op) {
  return parseDateMs(firstValue(
    op.updatedAt,
    op.dateUpdated,
    op.date_updated,
    op.date_updated_or_moved,
    op.lastStatusChangeAt,
    op.lastStageChangeAt,
    op.dateAdded,
    op.dateCreated,
    op.createdAt,
    op.date_created
  ));
}

function isInRecoveryWindow(op) {
  const ms = opportunityUpdatedMs(op);
  if (!Number.isFinite(ms)) return true; // si GHL no entrega fecha, no lo descartamos
  const start = parseDateMs(RECOVERY_START_LOCAL);
  const end = RECOVERY_END_LOCAL ? parseDateMs(RECOVERY_END_LOCAL) : Date.now();
  return ms >= start && ms <= end;
}

async function searchPipelineOpportunities(pipeline) {
  const found = [];
  for (let page = 1; page <= MAX_PAGES_PER_PIPELINE; page++) {
    const response = await ghlGet('/opportunities/search', {
      location_id: cfg.location_id,
      pipeline_id: pipeline.id,
      limit: PAGE_LIMIT,
      page,
      sortBy: 'updatedAt',
      sortOrder: 'desc'
    });

    const list = response.opportunities || response.data || response.items || (Array.isArray(response) ? response : []);
    if (!Array.isArray(list) || list.length === 0) break;

    for (const op of list) found.push(op);
    if (list.length < PAGE_LIMIT) break;
  }
  return found;
}

async function getOpportunityDetails(opportunityId) {
  if (!opportunityId) return {};
  try { return await ghlGet('/opportunities/' + encodeURIComponent(String(opportunityId)), {}); }
  catch (err) { return { _error: String(err && err.message || err) }; }
}

async function getContactDetails(contactId) {
  if (!contactId) return {};
  try { return await ghlGet('/contacts/' + encodeURIComponent(String(contactId)), {}); }
  catch (err) { return { _error: String(err && err.message || err) }; }
}

async function getContactNotes(contactId) {
  if (!contactId) return {};
  try { return await ghlGet('/contacts/' + encodeURIComponent(String(contactId)) + '/notes', {}); }
  catch (err) { return { _error: String(err && err.message || err) }; }
}

async function getContactAppointments(contactId) {
  if (!contactId) return {};
  try {
    return await ghlGet('/calendars/events/appointments', {
      locationId: cfg.location_id,
      contactId,
      limit: 100
    });
  } catch (err1) {
    try {
      return await ghlGet('/calendars/events', {
        locationId: cfg.location_id,
        contactId,
        limit: 100
      });
    } catch (err2) {
      return { _error: String(err2 && err2.message || err2) };
    }
  }
}

function normalizePayload(seed, opportunityResponse, contactResponse, notesResponse, appointmentsResponse) {
  const op = Object.assign({}, seed || {}, getOpportunityObject(opportunityResponse));
  const contact = getContactObject(contactResponse);
  const custom = mergeCustom(seed || {}, op, contact);

  const contactId = firstValue(op.contactId, op.contact_id, seed && seed.contactId, seed && seed.contact_id, contact.id, contact.contactId);
  const opportunityId = firstValue(op.id, op.opportunityId, op.opportunity_id, seed && seed.id, seed && seed.opportunityId);
  const pipelineId = firstValue(op.pipelineId, op.pipeline_id, seed && seed.pipelineId, seed && seed.pipeline_id);
  const pipelineName = firstValue(op.pipelineName, op.pipeline_name, pipelineNameById(pipelineId));
  const stageRaw = firstValue(op.pipelineStageName, op.stageName, op.stage, op.pipleline_stage, op.pipeline_stage, seed && seed.pipelineStageName, seed && seed.stageName, seed && seed.pipleline_stage);
  const stageActual = normalizeStageAlias(stageRaw);
  const status = firstValue(op.status, seed && seed.status);

  const ownerName = resolveOwnerName(
    op.assignedTo,
    op.assignedUserId,
    op.assigned_user_id,
    op.ownerId,
    op.owner_id,
    op.userId,
    op.assignedUser && op.assignedUser.id,
    op.assignedUser && op.assignedUser.email,
    op.assignedUser && op.assignedUser.name,
    op.owner && op.owner.id,
    op.owner && op.owner.email,
    op.owner && op.owner.name,
    seed && seed.assignedTo,
    seed && seed.assignedUserId,
    seed && seed.ownerId
  );

  const contactEmail = firstValue(contact.email, op.email, customValue(custom, 'contact_email'), customValue(custom, 'email'));
  const contactPhone = firstValue(contact.phone, op.phone, customValue(custom, 'contact_phone'), customValue(custom, 'phone'));
  const firstName = firstValue(contact.firstName, contact.first_name, op.firstName, op.first_name, seed && seed.first_name);
  const lastName = firstValue(contact.lastName, contact.last_name, op.lastName, op.last_name, seed && seed.last_name);
  const fullName = firstValue(contact.name, contact.fullName, contact.full_name, op.name, op.fullName, op.full_name, [firstName, lastName].filter(Boolean).join(' '));

  const normalized = {
    secret: cfg.crm_secret,
    event_type: 'ghl_opportunity',
    source: 'ghl_recovery_n8n_2026_07_28',
    contact_id: contactId,
    opportunity_id: opportunityId,
    pipeline_id: pipelineId,
    pipeline_name: pipelineName,
    stage_actual: stageActual,
    status,
    lead_value: firstValue(op.monetaryValue, op.value, op.leadValue, op.lead_value, ''),
    first_name: firstName,
    last_name: lastName,
    full_name: fullName,
    email: contactEmail,
    phone: contactPhone,
    country: firstValue(contact.country, op.country, seed && seed.country),
    company_name: firstValue(contact.companyName, contact.company_name, op.companyName, op.company_name, customValue(custom, 'business_name')),
    owner: ownerName,
    assigned_user_name: ownerName,
    assigned_user_email: firstValue(op.assignedUser && op.assignedUser.email, op.owner && op.owner.email, ''),
    date_created: firstValue(op.dateCreated, op.createdAt, op.dateAdded, op.date_created, seed && seed.date_created),
    date_updated_or_moved: firstValue(op.updatedAt, op.dateUpdated, op.date_updated, op.date_updated_or_moved, seed && seed.date_updated_or_moved),
    lead_source: firstValue(customValue(custom, 'fuente_origen'), customValue(custom, 'lead_source'), op.source, contact.source, deepGet(contact, 'attributionSource.sessionSource'), deepGet(contact, 'lastAttributionSource.sessionSource')),
    notes_text: getNotesText(notesResponse),
    custom: {
      fuente_origen: firstValue(customValue(custom, 'fuente_origen'), customValue(custom, 'lead_source'), op.source, contact.source, deepGet(contact, 'attributionSource.sessionSource'), deepGet(contact, 'lastAttributionSource.sessionSource')),
      lead_source: firstValue(customValue(custom, 'lead_source'), op.source, contact.source, deepGet(contact, 'attributionSource.sessionSource'), deepGet(contact, 'lastAttributionSource.sessionSource')),
      business_name: firstValue(customValue(custom, 'business_name'), contact.companyName, contact.company_name, op.companyName, op.company_name),
      contact_email: contactEmail,
      contact_phone: contactPhone,

      temperatura_lead: customValue(custom, 'temperatura_lead'),
      sin_datos_contacto: customValue(custom, 'sin_datos_contacto'),
      agendado_por: customValue(custom, 'agendado_por'),
      confirmo_asistencia_r1: customValue(custom, 'confirmo_asistencia_r1'),
