      estado_cuota_2: customValue(custom, 'estado_cuota_2'),
      fecha_cuota_3: customValue(custom, 'fecha_cuota_3'),
      estado_cuota_3: customValue(custom, 'estado_cuota_3'),
      motivo_perdida: customValue(custom, 'motivo_perdida')
    },
    appointment_r1: null,
    appointment_r2: null,
    appointment_r3: null,
    appointment_onboarding: null,
    raw: {
      recovery: true,
      recovery_start: RECOVERY_START_LOCAL,
      original_updated_ms: opportunityUpdatedMs(op),
      search_seed_keys: Object.keys(seed || {}),
      opportunity_detail_error: opportunityResponse && opportunityResponse._error || '',
      contact_detail_error: contactResponse && contactResponse._error || '',
      notes_error: notesResponse && notesResponse._error || '',
      appointments_error: appointmentsResponse && appointmentsResponse._error || ''
    }
  };

  const appointments = getAppointmentsArray(appointmentsResponse)
    .map(appt => ({ appt, detection: detectAppointmentType(appt) }))
    .filter(x => x.detection && x.detection.type)
    .map(x => normalizeAppointment(x.appt, x.detection))
    .filter(Boolean)
    .sort((a, b) => parseDateMs(b.start_time) - parseDateMs(a.start_time));

  for (const appt of appointments) {
    const key = 'appointment_' + String(appt.detected_type || '').toLowerCase();
    if (key in normalized && !normalized[key]) normalized[key] = appt;
  }

  return normalized;
}

const pipelines = PIPELINE_KEYS_TO_SCAN.map(pipelineByKey).filter(Boolean);
const seen = new Set();
const details = [];
let scanned = 0;
let eligible = 0;
let sent = 0;
let ok = 0;
let failed = 0;

for (const pipeline of pipelines) {
  const opportunities = await searchPipelineOpportunities(pipeline);
  scanned += opportunities.length;

  for (const seed of opportunities) {
    const opId = firstValue(seed.id, seed.opportunityId, seed.opportunity_id);
    const contactId = firstValue(seed.contactId, seed.contact_id);
    const dedupeKey = String(opId || '') + '|' + String(contactId || '');
    if (!dedupeKey.trim() || seen.has(dedupeKey)) continue;
    seen.add(dedupeKey);

    if (!isInRecoveryWindow(seed)) continue;
    eligible++;

    const opportunityResponse = await getOpportunityDetails(opId);
    const contactResponse = await getContactDetails(contactId);
    const notesResponse = await getContactNotes(contactId);
    const appointmentsResponse = await getContactAppointments(contactId);
    const payload = normalizePayload(seed, opportunityResponse, contactResponse, notesResponse, appointmentsResponse);

    sent++;
    try {
      const result = await appsScriptPost(payload);
      if (result && result.ok === false) failed++; else ok++;
      details.push({
        ok: !(result && result.ok === false),
        contact_id: payload.contact_id,
        opportunity_id: payload.opportunity_id,
        nombre: payload.full_name,
        pipeline: payload.pipeline_name,
        stage: payload.stage_actual,
        owner: payload.owner,
        r1_appt: payload.appointment_r1 && payload.appointment_r1.appointment_id || '',
        app_script_message: result && result.message || '',
        updated_sheet: result && result.updated_sheet || '',
        updated_row: result && result.updated_row || ''
      });
    } catch (err) {
      failed++;
      details.push({
        ok: false,
        contact_id: payload.contact_id,
        opportunity_id: payload.opportunity_id,
        nombre: payload.full_name,
        pipeline: payload.pipeline_name,
        stage: payload.stage_actual,
        owner: payload.owner,
        error: String(err && err.message || err)
      });
    }

    await sleep(SEND_DELAY_MS);
  }
}

return [{
  json: {
    ok: failed === 0,
    dry_run: DRY_RUN,
    client: cfg.client_name,
    recovery_start: RECOVERY_START_LOCAL,
    recovery_end: RECOVERY_END_LOCAL || new Date().toISOString(),
    pipelines_scanned: pipelines.map(p => p.name),
    scanned,
    eligible,
    sent,
    app_script_ok: ok,
    app_script_failed: failed,
    details
  }
}];
